class Solution {
    struct Trie {
        struct Node { int child[2] = {-1, -1}; };
        vector<Node> t = vector<Node>(1);
        void insert(long long x) {
            int p = 0;
            for (int b = 45; b >= 0; --b) {
                int v = (x >> b) & 1;
                if (t[p].child[v] == -1) {
                    int id = t.size();
                    t[p].child[v] = id;
                    t.push_back(Node());
                }
                p = t[p].child[v];
            }
        }
        long long query(long long x) {
            int p = 0;
            long long ans = 0;
            for (int b = 45; b >= 0; --b) {
                int v = (x >> b) & 1;
                if (t[p].child[1 - v] != -1) {
                    ans |= 1LL << b;
                    p = t[p].child[1 - v];
                } else {
                    p = t[p].child[v];
                }
            }
            return ans;
        }
    };
public:
    long long maxXor(int n, vector<vector<int>>& edges, vector<int>& values) {
        vector<vector<int>> g(n);
        for (auto& e : edges) {
            g[e[0]].push_back(e[1]);
            g[e[1]].push_back(e[0]);
        }
        vector<int> in(n), out(n), order;
        vector<long long> sum(n);
        function<void(int,int)> dfs = [&](int u, int parent) {
            in[u] = order.size();
            order.push_back(u);
            sum[u] = values[u];
            for (int v : g[u]) if (v != parent) {
                dfs(v, u);
                sum[u] += sum[v];
            }
            out[u] = order.size();
        };
        dfs(0, -1);
        vector<vector<int>> ending(n + 1);
        for (int u = 0; u < n; ++u) ending[out[u]].push_back(u);
        Trie trie;
        bool has = false;
        long long best = 0;
        for (int i = 0; i < n; ++i) {
            for (int u : ending[i]) {
                trie.insert(sum[u]);
                has = true;
            }
            if (has) best = max(best, trie.query(sum[order[i]]));
        }
        return best;
    }
};
